// Template: invoice_overdue/fr — rendu inline (versionné dans /n8n/email-templates)
const input = $('Execute Workflow Trigger').first().json;
const payload = input.payload || input;
const d = payload.data || {};
const c = d.client || {};
const org = d.org || d.organization || {};

const SUBJECT_TPL = "{{reminder.label}} — Facture {{number}} : {{amountDueLabel}} à régler";
const BODY_MJML = "<mjml><mj-body><mj-section><mj-column><mj-text>Bonjour {{client.name}},</mj-text><mj-text>{{reminder.message}}</mj-text><mj-text>Facture <strong>{{number}}</strong> — reste à régler : <strong>{{amountDueLabel}}</strong>, échéance dépassée de {{daysOverdue}} jour(s).</mj-text><mj-button href=\"{{portalUrl}}\">{{reminder.cta}}</mj-button><mj-text>{{reminder.closing}}</mj-text></mj-column></mj-section></mj-body></mjml>";

// Palier de relance (MVP5 §3.2) : le même événement invoice.overdue est émis à
// J+0, J+7, J+14 et J+30. Sans cette escalade, le client recevait quatre fois
// exactement le meme message.
const stage = Number(d.reminderStage ?? 0);
const daysOverdue = Number(d.daysOverdue ?? 0);

const REMINDER_TONES = {
  0: {
    label: 'Rappel',
    message: "L’échéance de cette facture est passée. Il s’agit probablement d’un simple oubli.",
    cta: 'Régler maintenant',
    closing: "Si le règlement est déjà parti, merci d’ignorer ce message.",
  },
  7: {
    label: 'Relance',
    message: 'Cette facture reste impayée une semaine après son échéance.',
    cta: 'Régler la facture',
    closing: 'En cas de difficulté, répondez à cet email : nous trouverons une solution.',
  },
  14: {
    label: 'Deuxième relance',
    message: 'Cette facture reste impayée deux semaines après son échéance.',
    cta: 'Régler sans attendre',
    closing: 'Merci de nous indiquer une date de règlement si le paiement doit être différé.',
  },
  30: {
    label: 'Dernière relance',
    message: 'Cette facture est impayée depuis un mois. Sans règlement ni réponse de votre part, le dossier sera transmis en recouvrement.',
    cta: 'Régler immédiatement',
    closing: "Contactez-nous dès aujourd’hui si vous contestez ce montant.",
  },
};

const reminder = REMINDER_TONES[stage] || REMINDER_TONES[0];

// Contexte de résolution des placeholders {{...}}
const ctx = {
  ...d,
  client: { name: c.name || '', email: c.email || '' },
  org: {
    name: org.name || '', logoUrl: org.logoUrl || '',
    brandColor: org.brandColor || '#111827',
    email: org.email || '', phone: org.phone || '',
  },
  reminder,
  daysOverdue,
  // Montants déjà formatés par l'application : le franc CFA n'a pas de
  // subdivision, ce nœud ne doit surtout pas diviser par 100.
  amountDueLabel: d.amountDueLabel || d.totalLabel || '',
  totalLabel: d.totalLabel || '',
  portalUrl: d.portalUrl || '',
  unsubscribeUrl: d.unsubscribeUrl || '',
};

function lookup(path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), ctx);
}
function resolve(tpl) {
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, p) => {
    const v = lookup(p);
    return v == null ? '' : String(v);
  });
}

// MJML -> HTML. mjml est optionnel dans l'image n8n : fallback si absent.
function compile(mjmlSource) {
  try {
    const mjml2html = require('mjml');
    const out = mjml2html(mjmlSource, { validationLevel: 'soft' });
    if (out && out.html) return out.html;
  } catch (e) {
    // mjml non installé -> dégradation contrôlée vers un HTML simple
  }
  const body = mjmlSource
    .replace(/<mj-button[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/mj-button>/g,
             '<p><a href="$1">$2</a></p>')
    .replace(/<mj-text[^>]*>([\s\S]*?)<\/mj-text>/g, '<p>$1</p>')
    .replace(/<\/?mj-(?:mjml|body|section|column|raw)[^>]*>/g, '')
    .replace(/<\/?mjml[^>]*>/g, '');
  return '<!doctype html><html><body>' + body + '</body></html>';
}

const to = [c.email].filter(Boolean);
if (!to.length) {
  throw new Error('Aucun destinataire résolu pour invoice_overdue (event ' + (payload.id || '?') + ')');
}

return [{ json: {
  eventId: payload.id || '',
  organizationId: payload.organizationId || '',
  to,
  subject: resolve(SUBJECT_TPL).trim(),
  html: compile(resolve(BODY_MJML)),
  pdfDownloadUrl: d.pdfUrl || d.pdfDownloadUrl || '',
  pdfFilename: (d.number ? String(d.number) : 'document') + '.pdf',
} }];
